var TYPE=require("../../tokenizer").TYPE,DELIM=TYPE.Delim,IDENT=TYPE.Ident,DIMENSION=TYPE.Dimension,PERCENTAGE=TYPE.Percentage,NUMBER=TYPE.Number,HASH=TYPE.Hash,COLON=TYPE.Colon,LEFTSQUAREBRACKET=TYPE.LeftSquareBracket,NUMBERSIGN=35,ASTERISK=42,PLUSSIGN=43,SOLIDUS=47,FULLSTOP=46,GREATERTHANSIGN=62,VERTICALLINE=124,TILDE=126;function getNode(e){switch(this.scanner.tokenType){case LEFTSQUAREBRACKET:return this.AttributeSelector();case HASH:return this.IdSelector();case COLON:return this.scanner.lookupType(1)===COLON?this.PseudoElementSelector():this.PseudoClassSelector();case IDENT:return this.TypeSelector();case NUMBER:case PERCENTAGE:return this.Percentage();case DIMENSION:this.scanner.source.charCodeAt(this.scanner.tokenStart)===FULLSTOP&&this.error("Identifier is expected",this.scanner.tokenStart+1);break;case DELIM:switch(this.scanner.source.charCodeAt(this.scanner.tokenStart)){case PLUSSIGN:case GREATERTHANSIGN:case TILDE:return e.space=null,e.ignoreWSAfter=!0,this.Combinator();case SOLIDUS:return this.Combinator();case FULLSTOP:return this.ClassSelector();case ASTERISK:case VERTICALLINE:return this.TypeSelector();case NUMBERSIGN:return this.IdSelector()}}}module.exports={getNode:getNode};